    const line = lineOf(source, open);
    if (close < 0) throw new TemplateError('unclosed-tag', { line }, `"{{" on line ${line} is not closed with "}}"`);
    const raw = source.slice(open + 2, close).trim();
    i = close + 2;
    if (raw.startsWith('!')) continue;
    const sigil = raw[0];
